import json,pathlib
p=pathlib.Path('WORKSPACE/MetroExodus_AR/03_translation/review/full_language_r1/combat')
ds=[json.loads(s) for s in (p/'decisions.jsonl').read_text(encoding='utf-8').splitlines()]
updates={197:'إنه يختبئ خلف الخزان هناك!',198:'ها هو ذلك الوغد! تحت ذلك الخزان!',199:'ذلك الوغد مختبئ تحت الخزان!',317:'كان ذلك اللعين مختبئًا تحت الخزان.',319:'ذلك الوغد تحت الخزان.',321:'كان مختبئًا تحت الخزان، ذلك اللعين!',455:'يا شباب... هل هناك أحمق مختبئ تحت ذلك الخزان، أم أنني أتوهم؟',457:'ما ذلك الشيء عند الخزان يا جماعة؟',459:'هاه؟ ماذا يوجد تحت ذلك الخزان يا جماعة؟',1599:'ها هو! خلف ذلك الخزان!',1600:'اللعين تحت ذلك الخزان!',1601:'أرى اللعين! إنه تحت ذلك الخزان!',1719:'كان ذلك اللعين الغبي مختبئًا تحت الخزان.',1721:'ذلك الوغد الملعون تحت الخزان.',1723:'كان مختبئًا تحت الخزان، ذلك اللعين الغبي!',1857:'يا رفاق، هناك أمر مريب تحت ذلك الخزان...',1859:'أظن أن هناك وغدًا عند ذلك الخزان...',1861:'هاه... ما ذلك الشيء تحت الخزان بحق الجحيم؟',3001:'يا شباب! إنه تحت ذلك الخزان!',3002:'أراه! ذلك الوغد خلف الخزان!',3003:'ها هو، خلف ذلك الخزان!',3121:'كان ذلك الوغد الملعون مختبئًا تحت الخزان.',3123:'ذلك اللعين تحت الخزان.',3125:'كان مختبئًا تحت الخزان، ذلك الوغد الملعون!',3259:'يا جماعة! ماذا يوجد تحت ذلك الخزان؟',3261:'يا شباب... ماذا يوجد عند ذلك الخزان؟',3263:'يا رفاق... ما ذلك الشيء عند الخزان بحق الجحيم؟',4360:'الزنديق تحت ذلك الخزان!',4361:'ها هو أيها الإخوة! عند ذلك الخزان!',4362:'إنه هناك، تحت الخزان!',4474:'كان الزنديق مختبئًا تحت ذلك الخزان.',4476:'كان الزنديق الملعون تحت الخزان!',4478:'تحت الخزان، هناك كان!',4606:'ماذا يوجد تحت ذلك الخزان أيها الإخوة؟',4608:'ماذا يوجد تحت ذلك الخزان؟ أترون أيها الإخوة؟',4610:'ماذا يوجد تحت ذلك الخزان؟ أترون؟'}
for i,t in updates.items():
    orig=ds[i]
    orig.pop('target',None)
    rows=[json.loads(s) for s in (p/'input.jsonl').read_text(encoding='utf-8').splitlines()] if 'rows' not in globals() else rows
    if t==rows[i]['target']: orig.update(decision='keep',reason='الأصل الروسي يحدد خزانًا؛ الترجمة الحالية سليمة مقارنة بالإنجليزية.')
    else: orig.update(decision='change',target=t,reason='حسم معنى tank من цистерна في الأصل الروسي: خزان؛ حفظ الجهات من الإنجليزية وتصحيح المخاطب أو التركيب حيث لزم.')
updates2={2500:('أبلغت بك الوقاحة هذا الحد؟ أخفِ ذلك السلاح واغرب عن وجهي!','الروسية Ты че там, оборзел تؤكد استنكار الوقاحة في تهديد الحارس؛ تصحيح الأمر بإخفاء السلاح والرحيل.'),2776:('آه، اللعنة... أصابني ذلك اللعين إصابة بالغة...','تؤكد الروسية Реально зацепило меня أن الإصابة للمتحدث؛ dad في الإنجليزية خطأ مطبعي واضح مكان bad ولا إشارة إلى أب.')}
for i,(t,reason) in updates2.items(): ds[i].update(decision='change',target=t,reason=reason)
(p/'decisions.jsonl').write_text(''.join(json.dumps(d,ensure_ascii=False)+'\n' for d in ds),encoding='utf-8')
for f in p.glob('batch*.json'):
    b=json.loads(f.read_text(encoding='utf-8-sig')); touched=False
    for i in list(updates)+list(updates2):
        if b['start']<=i<b['end']:
            d=ds[i]; b.setdefault('changes',{})[str(i)]={k:v for k,v in d.items() if k not in ('id','row')}; touched=True
    if touched:f.write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Resolved',len(updates)+len(updates2),'previous context decisions')